set -e; sdk="$HOME/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client"; node --input-type=module - "$sdk" "$HOME/.bun/bin" <<'JS'
const [sdk, bin] = process.argv.slice(2);
const { Client } = await import(sdk + '/index.js');
const { StdioClientTransport } = await import(sdk + '/stdio.js');
const client = new Client({ name: 'local-install-check', version: '1' });
const transport = new StdioClientTransport({command: bin + '/bun', args: [bin + '/gbrain', 'serve', '--surface', 'starter', '--advertise', 'verbs'], env: {HOME: process.env.HOME, GBRAIN_HOME: process.env.HOME}, stderr:'pipe'});
transport.stderr?.resume();
try {
  await client.connect(transport, {timeout: 15000});
  const {tools} = await client.listTools();
  if (!tools.some(t => t.name === 'recall')) throw Error('Missing recall');
  const result = await client.callTool({name:'recall',arguments:{entity:'gbrain-install-check'}});
  if (result.isError) throw Error('Recall failed');
  console.log('Local stdio MCP initialized, listed recall, and accepted a recall call.');
} finally { await client.close(); }
